import io,json,sys,tarfile
from pathlib import Path
root=Path('/mnt/lima-afsadata/afs-delivery/dfs-r3-sync-f03-20261008-r1');case='dfs-r3-meta-recovery-f03-20261008-r1'
files=[]
for p in (root/'logs').glob('*.log'):files.append(p)
for p in (root/'run').rglob('*'):
 if p.is_file() and not p.is_symlink():files.append(p)
for p in (root/'results').glob(case+'-*/*'):
 if p.is_file() and not p.is_symlink():files.append(p)
if 'a'=='ctl':files += [root/'state/meta/meta-store/wal']
else:files += [root/'state/node/dfs/catalog.wal',root/'state/node/dfs/device_epoch']
assert all(p.is_file() and not p.is_symlink() for p in files)
assert sum(p.stat().st_size for p in files)<8*2**20
with tarfile.open(fileobj=sys.stdout.buffer,mode='w:gz') as t:
 for p in sorted(set(files)):t.add(p,arcname=str(p.relative_to(root)),recursive=False)

